
(function(){
 window.WINTER_BOOK={name:'LIBRO_SERVICIOS_INVIERNO_2026_2027.pdf',data:''};

 function pdfBlob(){
   const bin=atob(WINTER_BOOK.data), bytes=new Uint8Array(bin.length);
   for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
   return new Blob([bytes],{type:'application/pdf'});
 }
 window.openWinterServiceBookPage=function(service){
   service=Number(service);
   const page=(typeof SERVICE_PAGES!=='undefined' && SERVICE_PAGES[service]) ? SERVICE_PAGES[service] : null;
   if(!page){alert('No se ha localizado la página del servicio '+service+'.');return;}
   const url=URL.createObjectURL(pdfBlob());
   const target=url+'#page='+page+'&zoom=page-width';
   const w=window.open(target,'_blank');
   if(!w) location.href=target;
   setTimeout(()=>URL.revokeObjectURL(url),120000);
 };

 // Intercepta el botón azul existente y lo lleva al PDF, no a las fotos del ZIP.
 document.addEventListener('click',function(e){
   const b=e.target.closest('.serviceSheetBtn');
   if(!b)return;
   const txt=(b.textContent||'');
   const mm=txt.match(/servicio\s+(\d+)/i);
   if(!mm)return;
   e.preventDefault(); e.stopImmediatePropagation();
   window.openWinterServiceBookPage(Number(mm[1]));
 },true);

 // Si una ficha no muestra botón porque ya no existen las fotos antiguas,
 // sustituimos el aviso por el botón hacia el Libro de Servicios.
 function repararBotones(){
   document.querySelectorAll('.serviceSheetMissing').forEach(x=>{
     const mm=(x.textContent||'').match(/servicio\s+(\d+)/i);
     if(mm){
       const n=Number(mm[1]);
       x.outerHTML='<button class="serviceSheetBtn" type="button">📄 Ver hoja del servicio '+n+'</button>';
     }
   });
 }
 new MutationObserver(repararBotones).observe(document.body,{childList:true,subtree:true});
 document.addEventListener('DOMContentLoaded',repararBotones);
 setTimeout(repararBotones,300);
})();
